"""Pydantic schemas and domain models for Sentinel Banking GraphRAG."""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, Field

from src.config import BANKING_CATEGORIES, TargetCategory

ActionType = Literal["CREATE_NEW", "SUPERSEDE_OLD"]


class GraphAction(BaseModel):
    """Structured graph mutation action generated by Curator extraction.

    Business logic:
    - target_node: Binds policy to fixed SME-governed ontology category.
    - action_type: CREATE_NEW for initial/independent policies, SUPERSEDE_OLD for updates.
    - extracted_rule: Actionable compliance rule extracted from source document.
    - superseded_document: Target document name when action_type is SUPERSEDE_OLD.
    - applies_to_customer: Target customer groups (NRI, MSME, Corporate, etc.).
    - requires_document: Required identity, tax, or collateral documents.
    """

    target_node: TargetCategory = Field(
        ...,
        description="Ontology category that the document belongs to.",
    )
    action_type: ActionType = Field(
        default="CREATE_NEW",
        description="CREATE_NEW for fresh guidance, SUPERSEDE_OLD for replacements.",
    )
    extracted_rule: str = Field(
        ...,
        min_length=10,
        description="Concise compliance rule extracted from the document.",
    )
    superseded_document: Optional[str] = Field(
        default=None,
        description="Name of old policy being replaced when action_type is SUPERSEDE_OLD.",
    )
    applies_to_customer: List[str] = Field(
        default_factory=list,
        description="Customer segments this policy applies to (for APPLIES_TO edges).",
    )
    requires_document: List[str] = Field(
        default_factory=list,
        description="Required documents/collateral for this policy (for REQUIRES edges).",
    )


class PolicyRecord(BaseModel):
    """Internal policy node record in knowledge graph."""

    name: str = Field(..., description="Unique policy document identifier.")
    category: str = Field(..., description="Banking ontology category.")
    issue_date: str = Field(default_factory=lambda: datetime.now(timezone.utc).strftime("%Y-%m-%d"))
    source_text: str = Field(..., description="Full or extracted source document text.")
    extracted_rule: str = Field(..., description="Normalized regulatory rule.")
    action_type: str = Field(default="CREATE_NEW")
    active: bool = Field(default=True, description="False if superseded by another policy.")
    superseded_by: Optional[str] = Field(default=None)
    supersedes: Optional[str] = Field(default=None)
    applies_to_customer: List[str] = Field(default_factory=list)
    requires_document: List[str] = Field(default_factory=list)
    embedding: Optional[List[float]] = Field(default=None)
    created_at: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    retired_at: Optional[str] = Field(default=None)


class ActivePolicy(BaseModel):
    """Verified active policy context returned from hybrid retrieval."""

    document_name: str = Field(..., description="Policy document identifier.")
    category: str = Field(..., description="SME-governed ontology category.")
    customer_types: List[str] = Field(
        default_factory=list,
        description="Customer types explicitly connected through APPLIES_TO edges.",
    )
    required_docs: List[str] = Field(
        default_factory=list,
        description="Required documents explicitly connected through REQUIRES edges.",
    )
    extracted_rule: str = Field(..., description="Normalized policy rule summary.")
    source_text: str = Field(..., description="Original policy source text.")
    score: float = Field(..., description="Raw hybrid retrieval score.")
    match_confidence: float = Field(
        ...,
        description="Normalized retrieval confidence percentage for UI display.",
    )


class ChatMessage(BaseModel):
    """A message in a chat conversation."""

    role: Literal["user", "assistant", "system"]
    content: str
    timestamp: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    citations: List[ActivePolicy] = Field(default_factory=list)


class ChatSession(BaseModel):
    """A saved conversation session."""

    session_id: str
    title: str = "New Conversation"
    created_at: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    updated_at: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    messages: List[ChatMessage] = Field(default_factory=list)


class ChatRequest(BaseModel):
    """Request payload for Copilot chat endpoint."""

    session_id: Optional[str] = None
    user_question: str
    enhance_query: bool = False


class ChatResponse(BaseModel):
    """Response payload for Copilot chat endpoint."""

    session_id: str
    response: str
    citations: List[ActivePolicy] = Field(default_factory=list)
    confidence_score: float = 0.0
    governance_status: str = "VERIFIED_ACTIVE"
    enhanced_query: Optional[str] = None


class EnhanceRequest(BaseModel):
    """Request payload for query expansion."""

    query: str


class EnhanceResponse(BaseModel):
    """Response payload for query expansion."""

    original_query: str
    enhanced_query: str


class IngestionResponse(BaseModel):
    """Result of document ingestion."""

    document_name: str
    category: str
    action_type: str
    extracted_rule: str
    superseded_document: Optional[str] = None
    applies_to_customer: List[str] = Field(default_factory=list)
    requires_document: List[str] = Field(default_factory=list)
    status: str = "SUCCESS"
    message: str = "Document successfully ingested into knowledge graph."
